package com.chubb.apac.claims.modulith.incident.repository;
import com.chubb.apac.claims.modulith.common.enums.Market;import com.chubb.apac.claims.modulith.incident.model.*;import java.time.Instant;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest class IncidentRepositoryTest {@Autowired IncidentRepository repository;@Test void findsOnlyByOwner(){Incident i=new Incident();i.setIncidentId("INC-1");i.setClaimantId("U1");i.setReportDate(Instant.now());i.setIncidentType(IncidentType.MOTOR_ACCIDENT);i.setLocation("L");i.setDescription("D");i.setMarket(Market.SG);i.setStatus(IncidentStatus.REPORTED);i.setCreatedBy("U1");i.setUpdatedBy("U1");repository.saveAndFlush(i);assertThat(repository.findByIncidentIdAndClaimantId("INC-1","U1")).isPresent();assertThat(repository.findByIncidentIdAndClaimantId("INC-1","U2")).isEmpty();}}
